package com.pharmnote.study;
import org.junit.Test;
import static org.junit.Assert.*;
public class SemanticHighlightsTest {
 @Test public void stylesAllExplicitKindsAndPreservesClinicalValues(){String source="[[ยา: Doxorubicin]] [[ขนาดยา: 60 mg/m² IV Day 1]] [[ข้อห้าม: เฉพาะที่ PDF ระบุ]] [[ข้อควรระวัง: ถ้าเข้าเงื่อนไข X]] [[ติดตาม: ค่าตาม PDF]] [[ยังไม่ยืนยัน: ยังไม่พบในหน้า 71–76]] [PDF 75; footnote n]";String html=RichSummary.body(source);for(String kind:new String[]{"drug","dose","contra","caution","monitor","uncertain"})assertTrue(kind,html.contains("semantic-"+kind));for(String value:new String[]{"Doxorubicin","60 mg/m² IV Day 1","เฉพาะที่ PDF ระบุ","ถ้าเข้าเงื่อนไข X","ค่าตาม PDF","ยังไม่พบในหน้า 71–76","[PDF 75; footnote n]"})assertTrue(value,html.contains(value));assertFalse(html.contains("[[ยา:"));}
 @Test public void worksInTwoColumnAndCardTablesWithoutBreakingColumns(){String source="| Drug | Dose |\n| --- | --- |\n| [[ยา: Drug-A]] | [[ขนาดยา: 2 mg/kg]] |\n\n| Drug | Dose | Source |\n| --- | --- | --- |\n| [[ยา: Drug-B]] | [[ขนาดยา: AUC 5 OR AUC 1.5]] | PDF 75 |";String html=RichSummary.body(source);assertTrue(html.contains("table-two"));assertTrue(html.contains("table-cards"));assertTrue(html.contains("Drug-A"));assertTrue(html.contains("Drug-B"));assertTrue(html.contains("2 mg/kg"));assertTrue(html.contains("AUC 5 OR AUC 1.5"));assertTrue(html.contains("PDF 75"));}
 @Test public void neverInfersContraindicationsOrDoseFromOrdinaryText(){String html=RichSummary.body("Doxorubicin 60 mg/m². ไม่พบข้อห้ามในส่วนที่ตรวจ");assertFalse(html.contains("class=\"semantic"));assertTrue(html.contains("ไม่พบข้อห้ามในส่วนที่ตรวจ"));}
 @Test public void leavesCodeLinksUnknownTagsAndMalformedMarkersAlone(){String source="`[[ยา: example]]`\n\n```text\n[[ขนาดยา: 999]]\n```\n\n[[other: value]]\n\n[link [[ยา: label]]](https://example.org/)\n\n[[ยา: unfinished";String html=RichSummary.body(source);assertFalse(html.contains("class=\"semantic"));assertTrue(html.contains("[[other: value]]"));assertTrue(html.contains("[[ยา: unfinished"));}
 @Test public void escapesDataAndDoesNotChangeDoseBoundaries(){String html=RichSummary.body("[[dose: ≤125 mg/m²; 5% A & B]]\n\n[[ยา: <script>alert(1)</script>]]");assertTrue(html.contains("≤125 mg/m²; 5% A &amp; B"));assertFalse(html.contains("<script>"));}
 @Test public void headingIndexKeepsReadableLabelsAndAnchorMatching(){String source="# [[ยา: Drug-A]]\n\n## รายละเอียด";String html=RichSummary.document(source);assertEquals("ยา: Drug-A",SummaryHeadings.extract(source).get(0).title);assertTrue(html.contains("id=\"pn-heading-0\""));assertTrue(html.contains("href=\"#pn-heading-0\""));}
 @Test public void legendIsOnlyPresentForStyledContent(){assertTrue(RichSummary.document("[[ยา: Drug-A]]").contains("<details class=semantic-key>"));assertFalse(RichSummary.document("ordinary note").contains("<details class=semantic-key>"));}
}
